fn transpose(arr: Vec<Vec<i8>>) -> Vec<Vec<i8>> {
    let m = arr.len(); // rows in original
    if m == 0 {
        return vec![];
    }
    let n = arr[0].len(); // columns in original

    // Create result matrix with n rows and m columns, filled with zeros
    let mut result = vec![vec![0; m]; n];

    for i in 0..m {
        for j in 0..n {
            result[j][i] = arr[i][j];
        }
    }

    result
}